    pub fn next_close_byte_demand(&self) -> Result<usize, &'static str> {
        Ok(match self.owners.front() {
            Some(Owner::Map(value)) => value.next_close_byte_demand().map_err(|_| "Neural ordered retirement demand refused")?,
